import{_ as o,a as t,b as a,c as r,d as i,e as d,f as s,g as n}from"./chunks/08h-preview-ipynb.DbtDiTJc.js";import{_ as l}from"./chunks/08f-preview-office.CXOHO4Wi.js";import{_ as c,o as p,c as h,a2 as u}from"./chunks/framework.DUZafPzB.js";const x=JSON.parse('{"title":"Preview","description":"","frontmatter":{},"headers":[],"relativePath":"features/preview.md","filePath":"features/preview.md","lastUpdated":1791645316000}'),m={name:"features/preview.md"};function f(w,e,b,g,v,k){return p(),h("div",null,[...e[0]||(e[0]=[u('<h1 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to &quot;Preview&quot;">​</a></h1><p>Click a file to preview it in the workspace without downloading to your laptop first. Desktop uses a <a href="/filebox/features/tabs">multi-tab workspace</a>; on phones preview swaps full-screen.</p><h2 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h2><p>Zoom and pan; the toolbar adjusts scale.</p><p><img src="'+o+'" alt="Image preview plot.png"></p><h2 id="markdown-text" tabindex="-1">Markdown / text <a class="header-anchor" href="#markdown-text" aria-label="Permalink to &quot;Markdown / text&quot;">​</a></h2><p>Markdown is rendered; plain text and code use a syntax-highlighted editor (read-only: find, wrap).</p><p><img src="'+t+'" alt="Markdown preview"></p><p><img src="'+a+'" alt="Code preview hello.py"></p><h2 id="quarto-r-markdown" tabindex="-1">Quarto / R Markdown <a class="header-anchor" href="#quarto-r-markdown" aria-label="Permalink to &quot;Quarto / R Markdown&quot;">​</a></h2><p><code>.qmd</code>, <code>.rmd</code>, and <code>.rmarkdown</code> open in the same read-only Monaco viewer with a custom <code>quarto</code> language — not download-only. Highlighting covers YAML / Quarto front matter, fenced chunks such as <code>{r}</code> / <code>{python}</code> (and plain fence language tags), optional <code>:::</code> fenced divs, and inline <code>`r …`</code> / <code>`python …`</code>. Chunk bodies reuse Monaco’s built-in highlighters for R, Python, Julia, SQL, shell, YAML, and similar. Plain <code>.md</code> still uses the rendered Markdown preview. A rich knitr-aware rendered Rmd view is a follow-up — this release is source highlighting only. File-list badges use the R colour category (RMD / QMD).</p><p><img src="'+r+'" alt="Quarto source preview qc-methods.qmd"></p><h2 id="pdf" tabindex="-1">PDF <a class="header-anchor" href="#pdf" aria-label="Permalink to &quot;PDF&quot;">​</a></h2><p>Built-in PDF viewer with Adaptive / percentage zoom (50 %–200 %) and continuous multi-page scrolling. The demo dataset’s <code>demo-report.pdf</code> is a 6-page synthetic lab report (tables, multi-panel figures, a correlation heatmap, equations) so the preview looks realistically dense.</p><p><img src="'+i+'" alt="PDF preview"></p><h2 id="csv-tsv" tabindex="-1">CSV / TSV <a class="header-anchor" href="#csv-tsv" aria-label="Permalink to &quot;CSV / TSV&quot;">​</a></h2><p>Table rendering with row/column counts and delimiter; toggle Raw / Copy.</p><p><img src="'+d+'" alt="CSV preview"></p><h2 id="office-optional" tabindex="-1">Office (optional) <a class="header-anchor" href="#office-optional" aria-label="Permalink to &quot;Office (optional)&quot;">​</a></h2><p>Word / PowerPoint convert to PDF on the Agent via LibreOffice; spreadsheets export one CSV per sheet. Requires <code>FILEBOX_AGENT_SOFFICE</code> — see <a href="/filebox/ops/office">Office preview</a>.</p><p><img src="'+l+'" alt="PowerPoint → PDF preview"></p><p>Settings has an <strong>Office preview</strong> toggle (browser-local preference, on by default).</p><h2 id="html" tabindex="-1">HTML <a class="header-anchor" href="#html" aria-label="Permalink to &quot;HTML&quot;">​</a></h2><p><code>.html</code> / <code>.htm</code> open in a <strong>sandboxed preview session</strong> (directory-scoped bearer token, TTL, per-session request/byte limits) — not a raw same-origin iframe. In document mode the Hub injects a locked absolute <code>&lt;base&gt;</code>, CSP and charset meta, and fixes anchors on navigation so relative links between files and in-page <code>#fragment</code> links work inside the sandbox; <code>../</code> is a hard boundary. Subresource / HEAD / XHR stay in locked-down raw mode. Document-mode CSP allows <code>data:</code> on <code>script-src</code> and <code>style-src</code>, so self-contained Quarto / Pandoc <code>data:text/css</code> stylesheets and <code>data:application/javascript</code> module scripts render with their intended fonts and layout (network egress remains limited to the tokenized preview origin). Use <strong>Source</strong> for the HTML source; open-in-new-window uses the same sandboxed pattern. Documents over 64 MiB are refused; like other HTML-class previews, files at or above 2 MiB ask for confirmation before loading.</p><p><img src="'+s+'" alt="HTML preview quarto-user.html"></p><h2 id="jupyter-notebook-ipynb" tabindex="-1">Jupyter notebook (<code>.ipynb</code>) <a class="header-anchor" href="#jupyter-notebook-ipynb" aria-label="Permalink to &quot;Jupyter notebook (`.ipynb`)&quot;">​</a></h2><p>Notebooks open through Filebox’s sandboxed HTML preview: the Hub washes nbformat JSON into a self-contained HTML document (markdown cells, code cells with execution counts, stream / error text with ANSI stripped, and png / jpeg / svg outputs). Mid-size png/jpeg payloads (decoded above ~350 KiB) get mild server-side recompression / downscale before embedding; payloads that remain above ~1.5 MiB are omitted with a note. Raw HTML, widgets, and JavaScript outputs are not rendered. This is <strong>not</strong> an interactive Jupyter runtime — read-only preview only. Large notebooks may ask for confirmation before loading (same oversized-file gate as other HTML-class previews).</p><p><img src="'+n+'" alt="Jupyter notebook preview qc-recovery.ipynb"></p><h2 id="supported-types" tabindex="-1">Supported types <a class="header-anchor" href="#supported-types" aria-label="Permalink to &quot;Supported types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Behavior</th></tr></thead><tbody><tr><td>Images</td><td>Zoom / pan (including TIFF)</td></tr><tr><td>PDF</td><td>Built-in viewer</td></tr><tr><td>Markdown</td><td>Rendered</td></tr><tr><td>Code / text / logs</td><td>Monaco read-only</td></tr><tr><td>Quarto / R Markdown (<code>.qmd</code> / <code>.rmd</code> / <code>.rmarkdown</code>)</td><td>Monaco source view (<code>quarto</code> language; YAML + chunks; not rendered)</td></tr><tr><td>HTML (<code>.html</code> / <code>.htm</code>)</td><td>Sandboxed session (locked <code>&lt;base&gt;</code> + CSP; relative / <code>#fragment</code> links; <code>data:</code> CSS/JS for self-contained Quarto/Pandoc; 64 MiB hard cap; 2 MiB confirm)</td></tr><tr><td>Jupyter notebook (<code>.ipynb</code>)</td><td>Hub-washed HTML in the same sandboxed session (read-only; mid-size png/jpeg mildly recompressed; oversized omitted; no widgets/JS)</td></tr><tr><td>CSV / TSV</td><td>Table</td></tr><tr><td>Word / PPT</td><td>Optional: Agent-side → PDF</td></tr><tr><td>Excel / ODS</td><td>Optional: each sheet → CSV</td></tr></tbody></table><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Desktop multi-tab: keep several files open, switch, pin, close in bulk; <code>Esc</code> closes the active tab, <code>←</code> / <code>→</code> step through the folder. See <a href="/filebox/features/tabs">Multi-tab preview</a>.</li><li>Very large files ask before loading so the browser stays responsive.</li><li>Click the path in the preview header to jump the file browser to that file&#39;s containing folder.</li><li>Use <strong>Download</strong> from the preview bar.</li><li>Without <code>soffice</code>, Office files remain downloadable but preview is unavailable.</li></ul>',32)])])}const M=c(m,[["render",f]]);export{x as __pageData,M as default};
